import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaLista = () => {
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  // Obtém o ID do utilizador (professor) do localStorage
  const userId = localStorage.getItem("userId");

  const fetchProfessorECursos = async () => {
    try {
      const resposta = await private_api.get(`/professores/${userId}`);

      if (resposta.status === 200) {
        // Ajuste conforme a estrutura da sua resposta
        if (resposta.data.cursos) {
          setCursos(resposta.data.cursos);
        } else if (resposta.data.professor?.cursos) {
          setCursos(resposta.data.professor.cursos);
        } else {
          setCursos([]);
        }
        setError(null);
      } else {
        setError("Erro ao buscar dados do professor");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
      setError("Erro ao carregar cursos. Tente novamente mais tarde.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (userId) {
      fetchProfessorECursos();
    } else {
      navigate("/login"); // Redireciona se não estiver logado
    }
  }, [userId, navigate]);

  if (loading) {
    return (
      <div className="d-flex justify-content-center mt-5">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <button className="nav-link active">Cursos</button>
        <button
          className="nav-link"
          onClick={() => navigate("/professoraulas")}
        >
          Aulas
        </button>
        <button
          className="nav-link"
          onClick={() => navigate("/professoravaliacoes")}
        >
          Avaliações
        </button>
      </nav>

      <h2 className="mb-3 text-center">Lista de Cursos à lecionar</h2>

      {error && (
        <div className="alert alert-danger w-75 text-center">{error}</div>
      )}

      {!error && cursos.length === 0 ? (
        <div className="alert alert-info w-75 text-center">
          Nenhum curso encontrado
        </div>
      ) : (
        <table className="table table-bordered bg-white w-75">
          <thead>
            <tr>
              <th>Curso</th>
              <th>Nível</th>
              <th>Data de Início</th>
              <th>Data de Fim</th>
              <th>Período</th>
            </tr>
          </thead>
          <tbody>
            {cursos.map((curso) => (
              <tr key={curso.id}>
                <td>{curso.nome}</td>
                <td>{curso.nivel}</td>
                <td>{new Date(curso.dataInicio).toLocaleDateString()}</td>
                <td>{new Date(curso.dataFim).toLocaleDateString()}</td>
                <td>{curso.periodo}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default LecionaLista;
